trait Describe {
    fn describe(&self) -> String;
}

struct Dog(String);
struct Robot(u32);

impl Describe for Dog {
    fn describe(&self) -> String { format!("dog named {}", self.0) }
}
impl Describe for Robot {
    fn describe(&self) -> String { format!("robot #{}", self.0) }
}

fn main() {
    let dog = Dog("Rex".into());
    let robot = Robot(7);
    let things: Vec<&dyn Describe> = vec![&dog, &robot];
    for thing in &things {
        println!("{}", thing.describe());
    }
}
